+        double a = 0, b = 0, c = 0;
+        if (!(in >> a >> b >> c)) {
+            throw std::invalid_argument("triangle needs three side lengths: " + line);
+        }
+        // Triangle constructor handles validation (a>0, b>0, c>0, and triangle inequality)
