--- a/src/triangle.cpp
+++ b/src/triangle.cpp
@@ -0,0 +1,39 @@
+#include "geometry/triangle.hpp"
+#include <stdexcept>
+#include <cmath>
+#include <algorithm>
+
+namespace geometry {
+
+Triangle::Triangle(double a, double b, double c)
+    : sideA(a), sideB(b), sideC(c) {
+    
+    // 檢查邊長是否為正數
+    if (a <= 0.0 || b <= 0.0 || c <= 0.0) {
+        throw std::invalid_argument("Triangle sides must be positive.");
+    }
+
+    // 檢查三角形不等式：任兩邊之和必須嚴格大於第三邊
+    // 1. a + b > c
+    // 2. a + c > b
+    // 3. b + c > a
+    if (a + b <= c || a + c <= b || b + c <= a) {
+        throw std::invalid_argument("Sides do not form a valid triangle.");
+    }
+}
+
+std::string Triangle::name() const {
+    return "triangle";
+}
+
+double Triangle::area() const {
+    // 海龍公式 (Heron's formula)
+    // s = (a + b + c) / 2
+    double s = (sideA + sideB + sideC) / 2.0;
+    
+    // Area = sqrt(s * (s - a) * (s - b) * (s - c))
+    // 由於建構子已經保證了有效的三角形，所以內部參數都 > 0 (或 >= 0 且乘積 > 0)
+    return std::sqrt(s * (s - sideA) * (s - sideB) * (s - sideC));
+}
+
+} // namespace geometry

--- a/tests/test_triangle.cpp
+++ b/tests/test_triangle.cpp
@@ -0,0 +1,90 @@
+#include "gtest/gtest.h"
+#include "geometry/triangle.hpp"
+#include "geometry/registry.hpp" // 引入 registry.hpp 以使用 parse_shape
+#include <stdexcept>
+#include <cmath>
+#include <string>
+
+using namespace geometry;
+
+// 測試 Triangle 類別
+TEST(TriangleTest, ValidTriangle) {
+    // 測試一個有效的三角形 (3, 4, 5)
+    Triangle t(3.0, 4.0, 5.0);
+    EXPECT_EQ(t.name(), "triangle");
+    // 面積 = 0.5 * base * height = 0.5 * 3 * 4 = 6.0
+    // 使用海龍公式: s = (3+4+5)/2 = 6.0. Area = sqrt(6*(6-3)*(6-4)*(6-5)) = sqrt(6*3*2*1) = sqrt(36) = 6.0
+    EXPECT_NEAR(t.area(), 6.0, 1e-9);
+
+    // 測試另一個有效的三角形 (5, 5, 5) - 等邊三角形
+    Triangle t_equi(5.0, 5.0, 5.0);
+    EXPECT_EQ(t_equi.name(), "triangle");
+    // 面積 = (sqrt(3)/4) * side^2 = (sqrt(3)/4) * 25
+    double expected_area = (std::sqrt(3.0) / 4.0) * 25.0;
+    EXPECT_NEAR(t_equi.area(), expected_area, 1e-9);
+}
+
+TEST(TriangleTest, InvalidSideLength) {
+    // 測試邊長為零
+    EXPECT_THROW({
+        Triangle t(0.0, 4.0, 5.0);
+    }, std::invalid_argument);
+
+    // 測試邊長為負數
+    EXPECT_THROW({
+        Triangle t(3.0, -4.0, 5.0);
+    }, std::invalid_argument);
+}
+
+TEST(TriangleTest, TriangleInequalityViolation) {
+    // 測試兩邊之和小於第三邊 (1 + 2 < 5)
+    EXPECT_THROW({
+        Triangle t(1.0, 2.0, 5.0);
+    }, std::invalid_argument);
+
+    // 測試兩邊之和等於第三邊 (退化三角形，不應被接受)
+    EXPECT_THROW({
+        Triangle t(1.0, 2.0, 3.0);
+    }, std::invalid_argument);
+}
+
+// 測試 parse_shape 解析功能
+TEST(TriangleTest, ParseShapeTriangle) {
+    // 1. 成功解析有效三角形
+    std::string valid_input = "triangle 3.0 4.0 5.0";
+    auto shape = parse_shape(valid_input);
+    ASSERT_NE(shape, nullptr);
+    EXPECT_EQ(shape->name(), "triangle");
+    // 驗證面積 (3, 4, 5)
+    EXPECT_NEAR(shape->area(), 6.0, 1e-9);
+
+    // 2. 成功解析另一個有效三角形
+    std::string valid_input_equi = "triangle 5 5 5";
+    shape = parse_shape(valid_input_equi);
+    ASSERT_NE(shape, nullptr);
+    EXPECT_EQ(shape->name(), "triangle");
+    double expected_area = (std::sqrt(3.0) / 4.0) * 25.0;
+    EXPECT_NEAR(shape->area(), expected_area, 1e-9);
+
+
+    // 3. 解析失敗：缺少參數 (只給了 "triangle")
+    std::string missing_params_input = "triangle";
+    EXPECT_THROW({
+        parse_shape(missing_params_input);
+    }, std::invalid_argument);
+
+    // 4. 解析失敗：參數格式錯誤 (例如，只給了兩個參數)
+    std::string wrong_params_input = "triangle 3.0 4.0";
+    EXPECT_THROW({
+        parse_shape(wrong_params_input);
+    }, std::invalid_argument);
+
+    // 5. 解析失敗：邊長無效 (雖然 Triangle 構造函數會拋出，但 parse_shape 應該能捕獲到輸入的格式問題，
+    // 這裡測試輸入本身導致的解析錯誤，例如負數或零，雖然最終會被 Triangle 構造函數捕獲，
+    // 但我們主要測試輸入格式的解析階段)
+    // 測試邊長為零的輸入，這會導致 Triangle 構造函數拋出
+    std::string zero_side_input = "triangle 0.0 4.0 5.0";
+    EXPECT_THROW({
+        parse_shape(zero_side_input);
+    }, std::invalid_argument);
+}

