+bool rb_peek_oldest(const RingBuf *rb, double *out) {
+    if (rb->count == 0) {
+        return false;
+    }
+    // Tail is the index of the oldest element (the one that would be popped next)
+    size_t tail = (rb->head + rb->capacity - rb->count) % rb->capacity;
+    *out = rb->data[tail];
+    return true;
+}
+
+void rb_clear(RingBuf *rb) {
+    rb->count = 0;
+    rb->head = 0;
+}
+
